<!DOCTYPE html>
<html>
<head>
    <style>
        body {
            background-color: #121212;
            color: white;
            font-family: Arial, sans-serif;
            display: flex;
            flex-direction: column;
            align-items: center;
            padding: 20px;
        }

        .bars {
            display: flex;
            align-items: flex-end;
            width: 95%;
            max-width: 800px;
            height: 300px;
            border: 1px solid #444;
            margin-bottom: 20px;
        }

        .bar {
            width: 100%;
            background-color: #5a7d9a;
            margin-right: 2px;
            position: relative;
            transition: background-color 0.3s, transform 0.2s;
            border-radius: 4px;
        }

        .bar.active {
            background-color: #ff6b6b;
            transform: scale(1.05);
        }

        button {
            padding: 10px 20px;
            margin-right: 10px;
            border: none;
            outline: none;
            cursor: pointer;
            background-color: #3a506b;
            color: white;
            border-radius: 4px;
        }

        button:hover {
            background-color: #2e3f5a;
        }
    </style>
</head>
<body>
    <div id="bars" class="bars"></div>
    <button id="sort">Sort</button>
    <button id="shuffle">Shuffle</button>
    <button id="reset">Reset</button>

    <script>
        window.viz = (function() {
            let _array = [];
            let current_i = 1;
            let j_pos = 0;
            let key_value = null;
            let is_in_inner_loop = false;
            let done_sorting = false;
            let highlightA = -1;
            let highlightB = -1;

            const getArray = () => _array.slice();
            const setArray = (arr) => {
                if (!Array.isArray(arr)) return;
                _array = arr.slice();
                drawBars();
            };

            const sortedCheck = () => {
                for (let i = 1; i < _array.length; i++) {
                    if (_array[i] < _array[i - 1]) return false;
                }
                return true;
            };

            function drawBars() {
                const container = document.getElementById('bars');
                container.innerHTML = '';
                let max_val = Math.max(..._array) || 1;

                _array.forEach((val, idx) => {
                    const bar = document.createElement('div');
                    bar.className = 'bar';
                    if (idx === highlightA || idx === highlightB) bar.classList.add('active');
                    const height_percent = (val / max_val) * 80;
                    bar.style.height = `${height_percent}%`;
                    container.appendChild(bar);
                });
            }

            function sortStep() {
                if (done_sorting || current_i >= _array.length) return true;

                highlightA = -1;
                highlightB = -1;

                if (!is_in_inner_loop) {
                    key_value = _array[current_i];
                    j_pos = current_i - 1;
                    is_in_inner_loop = true;

                    if (j_pos >= 0 && _array[j_pos] > key_value) {
                        highlightA = j_pos;
                        highlightB = j_pos + 1;
                        _array[j_pos + 1] = _array[j_pos];
                        j_pos--;
                    } else if (j_pos < 0) {
                        highlightA = -1;
                        _array[0] = key_value;
                        current_i++;
                        is_in_inner_loop = false;
                    }
                } else {
                    if (j_pos >= 0 && _array[j_pos] > key_value) {
                        highlightA = j_pos;
                        highlightB = j_pos + 1;
                        _array[j_pos + 1] = _array[j_pos];
                        j_pos--;
                    } else {
                        const pos_insert = j_pos + 1;
                        _array[pos_insert] = key_value;

                        current_i++;
                        is_in_inner_loop = false;

                        if (current_i >= _array.length) done_sorting = true;
                    }
                }

                drawBars();
                return sortedCheck();
            }

            function reset() {
                const newArr = Array.from({ length: 20 }, () => Math.floor(Math.random() * 100) + 5);
                setArray(newArr);
                current_i = 1;
                j_pos = 0;
                key_value = null;
                is_in_inner_loop = false;
                done_sorting = false;
            }

            return {
                array: getArray,
                setArray,
                sortStep,
                sorted: () => sortedCheck(),
                _reset: reset
            };
        })();

        window.viz._reset();

        document.getElementById('sort').addEventListener('click', () => {
            let interval = setInterval(() => {
                if (window.viz.sortStep()) clearInterval(interval);
            }, 50);
        });

        document.getElementById('shuffle').addEventListener('click', () => {
            const shuffled = window.viz.array();
            for (let i = shuffled.length - 1; i > 0; i--) {
                const j = Math.floor(Math.random() * (i + 1));
                [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
            }
            window.viz.setArray(shuffled);
        });

        document.getElementById('reset').addEventListener('click', () => {
            window.viz._reset();
        });
    </script>
</body>
</html>
